#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const PROBLEMS_PATH = '.fastops/marketplace/problems.jsonl';
const MODEL_ROUTER = '.fastops/model-router.js';

function readProblems(limit = 50) {
    if (!fs.existsSync(PROBLEMS_PATH)) return [];
    const content = fs.readFileSync(PROBLEMS_PATH, 'utf8');
    return content.trim().split('\n')
        .slice(0, limit)
        .map(line => {
            try { return JSON.parse(line); } 
            catch { return null; }
        })
        .filter(p => p && p.status === 'open' && !p.claimed_by);
}

function scoreModelForProblem(model, problem) {
    // Use the existing model router scoring
    const modelRouter = require(path.resolve(MODEL_ROUTER));
    if (typeof modelRouter.scoreModel === 'function') {
        return modelRouter.scoreModel(model, problem);
    }
    // Fallback: simple keyword matching
    const problemText = `${problem.title} ${problem.description || ''}`.toLowerCase();
    const modelName = model.toLowerCase();
    if (problemText.includes('code') && modelName.includes('deepseek')) return 0.8;
    if (problemText.includes('reason') && modelName.includes('claude')) return 0.7;
    return 0.5;
}

function pickBestModel(problem) {
    const models = ['deepseek', 'claude', 'grok', 'kimi', 'mistral'];
    let bestScore = -1;
    let bestModel = null;

    for (const model of models) {
        const score = scoreModelForProblem(model, problem);
        if (score > bestScore) {
            bestScore = score;
            bestModel = model;
        }
    }
    return { model: bestModel, score: bestScore };
}

function dispatchSession(problem, model) {
    const task = JSON.stringify({
        type: 'marketplace_problem',
        problem_id: problem.id,
        title: problem.title,
        description: problem.description
    });

    // Use city-session with the model and task
    const cmd = `node .fastops/city-session.js --model ${model} --task '${task}'`;
    console.log(`Dispatching: ${cmd}`);
    try {
        execSync(cmd, { stdio: 'inherit' });
        return true;
    } catch (error) {
        console.error(`Dispatch failed: ${error.message}`);
        return false;
    }
}

function logRouting(problem, model, score, success) {
    const ledgerEntry = {
        timestamp: new Date().toISOString(),
        event: 'auto_route',
        problem_id: problem.id,
        model,
        score,
        success,
        metadata: { title: problem.title }
    };

    fs.appendFileSync('.fastops/city-ledger.jsonl', 
        JSON.stringify(ledgerEntry) + '\n');
}

function main() {
    const args = process.argv.slice(2);
    const dryRun = args.includes('--dry-run');
    const limitArg = args.find(arg => arg.startsWith('--limit='));
    const limit = limitArg ? parseInt(limitArg.split('=')[1]) : 10;

    console.log(`Auto-router scanning ${PROBLEMS_PATH} (limit: ${limit})`);

    const problems = readProblems(limit);
    console.log(`Found ${problems.length} open, unclaimed problems`);

    for (const problem of problems) {
        const { model, score } = pickBestModel(problem);
        console.log(`Problem ${problem.id}: "${problem.title}" -> ${model} (score: ${score.toFixed(2)})`);

        if (!dryRun && model) {
            const success = dispatchSession(problem, model);
            logRouting(problem, model, score, success);

            if (success) {
                console.log(`✓ Routed to ${model}`);
            }
        }
    }

    if (dryRun) {
        console.log('Dry run complete - no sessions dispatched');
    }
}

if (require.main === module) {
    main();
}
